<?php
require_once __DIR__.'/../app/Core/DB.php';require_once __DIR__.'/../app/Services/AnggaranDocumentService.php';
$db=DB::getInstance();$ok=static function($v,$m){if(!$v)throw new RuntimeException('FAIL: '.$m);echo"PASS: $m\n";};$user=$db->query("SELECT * FROM user_sesendok_biila WHERE kd_wilayah='76.01' AND kd_opd='1.03.0.00.0.00.01.0000' AND tahun=2026 AND disable=0 LIMIT 1")->fetch();$service=new AnggaranDocumentService($user);$groups=$service->groups('dpa');$sub=$groups[0]['kd_sub_keg'];$rows=$service->accountMonthlyRows('dpa',$sub);$ok(count($rows)>0,'list rencana dibentuk per rekening belanja level akhir');$target=$rows[0];$months=array_fill(1,12,0);$months[1]=$target['pagu']/2;$months[2]=$target['pagu']/2;$saved=$service->saveAccountMonthly('dpa',$sub,$target['kd_akun'],$months);$match=array_values(array_filter($saved,fn($r)=>$r['kd_akun']===$target['kd_akun']))[0];$ok(abs($match['total_rencana']-$target['pagu'])<.01,'rekening dibagi per bulan maksimal tepat sebesar pagu rekening');$over=$months;$over[3]=1;try{$service->saveAccountMonthly('dpa',$sub,$target['kd_akun'],$over);$guard=false;}catch(Throwable$e){$guard=true;}$ok($guard,'pembagian rekening melebihi pagu ditolak');$pdf=$service->exportRegulatoryPdf('dpa');$ok(str_starts_with($pdf,'%PDF'),'PDF regulasi normal valid');$ok(!str_contains($pdf,'Rencana Penarikan Dana per Bulan')&&!str_contains($pdf,'Tim Anggaran Pemerintah Daerah'),'PDF rincian tidak ditempeli tabel rencana bulanan/TAPD');$view=file_get_contents(__DIR__.'/../app/Views/anggaran/monthly_account.php');$ok(str_contains($view,'Kembali ke Uraian Sub Kegiatan')&&str_contains($view,'monthly-account-scroll'),'rencana rekening memakai halaman list tersendiri dan scroll horizontal');$controller=file_get_contents(__DIR__.'/../app/Controllers/UserOpdController.php');$ok(str_contains($controller,'pegawai_id')&&str_contains($controller,'db_asn_pemda_neo'),'user OPD dan kepala OPD bersumber dari master kepegawaian');echo"PHASE 33 ACCOUNT MONTHLY/EMPLOYEE/PDF TESTS COMPLETE\n";
